		if self.left_leg_pose != Default::default() { bytes = self.write_for_index(bytes, 20); }
		if self.right_leg_pose != Default::default() { bytes = self.write_for_index(bytes, 21); }
        bytes = <Single as SliceSerializable<u8>>::write(bytes, 255);
