		if self.got_fish != bool::default() { bytes = self.write_for_index(bytes, 17); }
		if self.moistness_level != i32::default() { bytes = self.write_for_index(bytes, 18); }
        bytes = <Single as SliceSerializable<u8>>::write(bytes, 255);
