	#[inline(always)]
	pub fn get_write_size_for_index(&self, index: usize) -> usize {
		match index {
			0 => 1,
			1 => 5,
			2 => 1 + if let Some(value) = &self.custom_name { value.to_bytes().len() } else { 0 },
			3 => 1,
			4 => 1,
			5 => 1,
			6 => 1,
			7 => 5,
			8 => 1,
			9 => 4,
			10 => unimplemented!(),
			11 => 1,
			12 => 5,
			13 => 5,
			14 => 1 + if self.sleeping_pos.is_some() { 8 } else { 0 },
			15 => 1,
			16 => 5,
			_ => unreachable!()
		}
	}

	#[inline(always)]
