impl Metadata for VindicatorMetadata {
        fn has_changed(&self) -> bool {
            match self.changes {
                MetadataChanges::NoChanges => false,
                MetadataChanges::SingleChange { index: _ } => true,
                MetadataChanges::ManyChanges { indices } => true,
            }
        }

        fn clear_all_changes(&mut self) {
            self.changes = MetadataChanges::NoChanges;
        }
    
    fn get_changes_write_size(&self) -> usize {
        match self.changes {
            MetadataChanges::NoChanges => 0,
            MetadataChanges::SingleChange { index } => {
                1 + 2 + self.get_write_size_for_index(index)
            },
            MetadataChanges::ManyChanges { indices } => {
                let mut size = 1;
				if indices[0] { size += 2 + self.get_write_size_for_index(0); }
				if indices[1] { size += 2 + self.get_write_size_for_index(1); }
				if indices[2] { size += 2 + self.get_write_size_for_index(2); }
				if indices[3] { size += 2 + self.get_write_size_for_index(3); }
				if indices[4] { size += 2 + self.get_write_size_for_index(4); }
				if indices[5] { size += 2 + self.get_write_size_for_index(5); }
				if indices[6] { size += 2 + self.get_write_size_for_index(6); }
				if indices[7] { size += 2 + self.get_write_size_for_index(7); }
				if indices[8] { size += 2 + self.get_write_size_for_index(8); }
				if indices[9] { size += 2 + self.get_write_size_for_index(9); }
				if indices[10] { size += 2 + self.get_write_size_for_index(10); }
				if indices[11] { size += 2 + self.get_write_size_for_index(11); }
				if indices[12] { size += 2 + self.get_write_size_for_index(12); }
				if indices[13] { size += 2 + self.get_write_size_for_index(13); }
				if indices[14] { size += 2 + self.get_write_size_for_index(14); }
				if indices[15] { size += 2 + self.get_write_size_for_index(15); }
				if indices[16] { size += 2 + self.get_write_size_for_index(16); }
                size
            }
        }
    }

    unsafe fn write_changes<'b>(&mut self, mut bytes: &'b mut [u8]) -> &'b mut [u8] {
        match self.changes {
            MetadataChanges::NoChanges => {},
            MetadataChanges::SingleChange { index } => {
                bytes = self.write_for_index(bytes, index);
                bytes = <Single as SliceSerializable<u8>>::write(bytes, 255);
            },
            MetadataChanges::ManyChanges { indices } => {
				if indices[0] { bytes = self.write_for_index(bytes, 0); }
				if indices[1] { bytes = self.write_for_index(bytes, 1); }
				if indices[2] { bytes = self.write_for_index(bytes, 2); }
				if indices[3] { bytes = self.write_for_index(bytes, 3); }
				if indices[4] { bytes = self.write_for_index(bytes, 4); }
				if indices[5] { bytes = self.write_for_index(bytes, 5); }
				if indices[6] { bytes = self.write_for_index(bytes, 6); }
				if indices[7] { bytes = self.write_for_index(bytes, 7); }
				if indices[8] { bytes = self.write_for_index(bytes, 8); }
				if indices[9] { bytes = self.write_for_index(bytes, 9); }
				if indices[10] { bytes = self.write_for_index(bytes, 10); }
				if indices[11] { bytes = self.write_for_index(bytes, 11); }
				if indices[12] { bytes = self.write_for_index(bytes, 12); }
				if indices[13] { bytes = self.write_for_index(bytes, 13); }
				if indices[14] { bytes = self.write_for_index(bytes, 14); }
				if indices[15] { bytes = self.write_for_index(bytes, 15); }
				if indices[16] { bytes = self.write_for_index(bytes, 16); }
                bytes = <Single as SliceSerializable<u8>>::write(bytes, 255);
            }
        }
        bytes
    }

    fn get_non_default_write_size(&self) -> usize {
        let mut size = 1;
		if self.shared_flags != u8::default() { size += 2 + self.get_write_size_for_index(0); }
		if self.air_supply != i32::default() { size += 2 + self.get_write_size_for_index(1); }
		if self.custom_name != Default::default() { size += 2 + self.get_write_size_for_index(2); }
		if self.custom_name_visible != bool::default() { size += 2 + self.get_write_size_for_index(3); }
		if self.silent != bool::default() { size += 2 + self.get_write_size_for_index(4); }
		if self.no_gravity != bool::default() { size += 2 + self.get_write_size_for_index(5); }
		if self.pose != crate::types::Pose::default() { size += 2 + self.get_write_size_for_index(6); }
		if self.ticks_frozen != i32::default() { size += 2 + self.get_write_size_for_index(7); }
		if self.living_entity_flags != u8::default() { size += 2 + self.get_write_size_for_index(8); }
		if self.health != f32::default() { size += 2 + self.get_write_size_for_index(9); }
		if self.effect_particles != () { size += 2 + self.get_write_size_for_index(10); }
		if self.effect_ambience != bool::default() { size += 2 + self.get_write_size_for_index(11); }
		if self.arrow_count != i32::default() { size += 2 + self.get_write_size_for_index(12); }
		if self.stinger_count != i32::default() { size += 2 + self.get_write_size_for_index(13); }
		if self.sleeping_pos != Default::default() { size += 2 + self.get_write_size_for_index(14); }
		if self.mob_flags != u8::default() { size += 2 + self.get_write_size_for_index(15); }
		if self.is_celebrating != bool::default() { size += 2 + self.get_write_size_for_index(16); }
        size
    }

    unsafe fn write_non_default<'b>(&self, mut bytes: &'b mut [u8]) -> &'b mut [u8] {
		if self.shared_flags != u8::default() { bytes = self.write_for_index(bytes, 0); }
		if self.air_supply != i32::default() { bytes = self.write_for_index(bytes, 1); }
		if self.custom_name != Default::default() { bytes = self.write_for_index(bytes, 2); }
		if self.custom_name_visible != bool::default() { bytes = self.write_for_index(bytes, 3); }
		if self.silent != bool::default() { bytes = self.write_for_index(bytes, 4); }
		if self.no_gravity != bool::default() { bytes = self.write_for_index(bytes, 5); }
		if self.pose != crate::types::Pose::default() { bytes = self.write_for_index(bytes, 6); }
		if self.ticks_frozen != i32::default() { bytes = self.write_for_index(bytes, 7); }
		if self.living_entity_flags != u8::default() { bytes = self.write_for_index(bytes, 8); }
		if self.health != f32::default() { bytes = self.write_for_index(bytes, 9); }
		if self.effect_particles != () { bytes = self.write_for_index(bytes, 10); }
		if self.effect_ambience != bool::default() { bytes = self.write_for_index(bytes, 11); }
		if self.arrow_count != i32::default() { bytes = self.write_for_index(bytes, 12); }
		if self.stinger_count != i32::default() { bytes = self.write_for_index(bytes, 13); }
		if self.sleeping_pos != Default::default() { bytes = self.write_for_index(bytes, 14); }
		if self.mob_flags != u8::default() { bytes = self.write_for_index(bytes, 15); }
		if self.is_celebrating != bool::default() { bytes = self.write_for_index(bytes, 16); }
        bytes = <Single as SliceSerializable<u8>>::write(bytes, 255);
        bytes
    }
}

